#!/usr/bin/env python3
"""Gera /home/dev/plataforma/laco/decomposicao/L1.json (linha L1 imagens).
Roda-se várias vezes durante a escrita: cada execução regrava o JSON inteiro (salvamento incremental)."""
import json, datetime
from pathlib import Path

SAIDA = Path("/home/dev/plataforma/laco/decomposicao/L1.json")
LINHA = "L1 imagens"
HOJE = "2026-09-05"

ITENS = []


def it(id, prio, tam, dep, hip, portao, ref, papeis, origem, pai=None, fontes=None, bloqueio=None):
    ITENS.append({
        "id": id, "linha": LINHA, "prioridade": prio, "estado": "pendente",
        "dependencias": dep, "hipotese": hip, "portao_de_pronto": portao, "refutacao": ref,
        "papeis": papeis, "tamanho": tam, "tentativas": 0, "turno": None, "bloqueio": bloqueio,
        "pai": pai, "origem": origem, "fontes": fontes or [],
    })


