def salvar():
    ids = [i["id"] for i in ITENS]
    assert len(ids) == len(set(ids)), "id duplicado"
    fontes = sorted({u for i in ITENS for u in i["fontes"]})
    doc = {
        "linha": LINHA,
        "gerado_em": HOJE,
        "gerador": "scratchpad/l1/gera_l1.py (agente L1 imagens, 05/09/2026)",
        "brief": "laco/decomposicao/BRIEF.md (05/09/2026); decisões de conceito em L1_CONCEITO.md",
        "itens_existentes_detalhados": ["L1-01-ingest-raster", "L1-02-tiles-token", "L1-03-conectores-sensores", "L1-04-serie-temporal", "L1-05-ia-na-entrada"],
        "nota_sobre_pais": "L1-01..L1-05 continuam no estado.json; quando trabalhados viram `parcial` com os filhos `-a..` daqui como dependência. L1-06 foi proposto pela decomposição L3L6 e está aqui com o mesmo id. L1-07 em diante são itens novos e independentes.",
        "n_itens": len(ITENS),
        "numeracao": "ids L1-11, L1-17, L1-22, L1-26, L1-28 e as letras L1-03-g/i/j/m/o/r, L1-04-b/d, L1-02-j/k/l não existem: foram fundidos em itens vizinhos durante a decomposição para ficar em 60 itens (ex.: legenda entrou em L1-02-f, pegadas em L1-07, MDT/MDS de LiDAR em L1-03-q, exportação em massa em L1-20, CLI em L1-01-h).",
        "n_por_prioridade": {str(p): sum(1 for i in ITENS if i["prioridade"] == p) for p in range(1, 6)},
        "n_por_tamanho": {t: sum(1 for i in ITENS if i["tamanho"] == t) for t in "PMG"},
        "dependencias_externas_propostas": DEPS_EXTERNAS,
        "medido_na_casa_em_2026-09-05": MEDIDO,
        "fontes_testadas_http_200_em_2026-09-05": fontes,
        "itens": ITENS,
    }
    SAIDA.write_text(json.dumps(doc, ensure_ascii=False, indent=1))
    print(len(ITENS), "itens →", SAIDA)


if __name__ == "__main__":
    salvar()
